import java.util.*;

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public void add(int value) {
        if (root == null) {
            root = new Node(value);
        } else {
            root.add(value);
        }
    }

    public void preOrder(ArrayList<Integer> list) {
        if (root != null) {
            root.preOrder(list);
        }
    }

    // Método para encontrar o valor mais próximo de N em O(h)
    public int findClosest(int N) {
        int closest = root.value;
        Node current = root;

        while (current != null) {
            if (Math.abs(current.value - N) < Math.abs(closest - N)) {
                closest = current.value;
            }

            if (N < current.value) {
                current = current.left;
            } else if (N > current.value) {
                current = current.right;
            } else {
                break; // Encontrado valor exato
            }
        }
        return closest;
    }
}

