class TabelaHash {
    private ArrayList<Pair>[] tabela;
    private int tamanho;

    public TabelaHash(int tamanho) {
        this.tamanho = tamanho;
        this.tabela = new ArrayList[tamanho];
        for (int i = 0; i < tamanho; i++) {
            this.tabela[i] = new ArrayList<>();
        }
    }

    private int hash(int key) {
        return key % tamanho;
    }

    public void put(int key, String value) {
        int pos = hash(key);
        ArrayList<Pair> lista = tabela[pos];

        // Verifica se a chave já existe (atualiza o valor)
        for (Pair p : lista) {
            if (p.key == key) {
                p.value = value;
                return;
            }
        }

        // Se não existir, adiciona um novo par
        lista.add(new Pair(key, value));
    }

    public void remove(int key) {
        int pos = hash(key);
        ArrayList<Pair> lista = tabela[pos];

        // Remove a primeira ocorrência da chave (se existir)
        Iterator<Pair> iterator = lista.iterator();
        while (iterator.hasNext()) {
            Pair p = iterator.next();
            if (p.key == key) {
                iterator.remove();
                return;
            }
        }
    }

    public String keys() {
        ArrayList<Integer> chaves = new ArrayList<>();
        for (ArrayList<Pair> lista : tabela) {
            for (Pair p : lista) {
                chaves.add(p.key);
            }
        }
        Collections.sort(chaves);
        return chaves.toString();
    }

    public String values() {
        ArrayList<String> valores = new ArrayList<>();
        for (ArrayList<Pair> lista : tabela) {
            for (Pair p : lista) {
                valores.add(p.value);
            }
        }
        Collections.sort(valores);
        return valores.toString();
    }

    public void imprimirEstado() {
        System.out.print("[");
        for (int i = 0; i < tabela.length; i++) {
            System.out.print(tabela[i]);
            if (i < tabela.length - 1) {
                System.out.print(", ");
            }
        }
        System.out.println("]");
    }
}

